# owner: platform
"""Weekly timesheet rows built from a list of shifts."""

from typing import List, Iterable
from hourglass.models import Shift


def _check(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts to total")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("shift has no worker name")


def _tally(shifts: List[Shift]) -> dict:
    totals = {}
    for shift in shifts:
        count, minutes = totals.get(shift.worker, (0, 0))
        minutes += shift.span.minutes
        totals[shift.worker] = (count + 1, minutes)
    return totals


def _row(name: str, count: int, minutes: int) -> str:
    noun = "shift" if count == 1 else "shifts"
    hours = f"{minutes / 60:.1f}"
    return f"{name}: {count} {noun}, {hours} hours"


# ---
def timesheet_rows(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, busiest first, ties by name."""
    shifts = list(shifts)
    _check(shifts)
    totals = _tally(shifts)
    order = sorted(
        totals, key=lambda name: (-totals[name][1], name)
    )
    return [_row(name, *totals[name]) for name in order]

