# owner: platform
import unittest

from hourglass.timesheet import timesheet_rows
from hourglass.parsing import parse_span
from hourglass.models import Shift


def make_shift(worker, text, day="mon"):
    return Shift(worker, day, parse_span(text))


def busy_week():
    return [
        make_shift("Bea", "09:00-11:00"),
        make_shift("Ana", "09:00-17:30"),
        make_shift("Ana", "09:00-12:00", "tue")
    ]


class TimesheetTests(unittest.TestCase):
    # ---
    def test_busiest_worker_comes_first(self):
        rows = timesheet_rows(busy_week())
        self.assertEqual(rows, [
            "Ana: 2 shifts, 11.5 hours",
            "Bea: 1 shift, 2.0 hours"
        ])

    # ---
    def test_hours_use_one_decimal_place(self):
        shift = make_shift("Ana", "09:00-09:20")
        rows = timesheet_rows([shift])
        self.assertEqual(rows, ["Ana: 1 shift, 0.3 hours"])

    # ---
    def test_ties_are_ordered_by_name(self):
        rows = timesheet_rows([
            make_shift("Zoe", "09:00-10:00"),
            make_shift("Amy", "10:00-11:00")
        ])
        self.assertTrue(rows[0].startswith("Amy"))

    # ---
    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_rows([])

    # ---
    def test_blank_worker_raises(self):
        for name in ("", "   "):
            with self.assertRaises(ValueError):
                shift = make_shift(name, "09:00-10:00")
                timesheet_rows([shift])
